#!/usr/bin/env python3
"""Odtwarza filechk_offsets z scripts/Makefile.lib:494-515 w Pythonie.
Wejscie: plik .s wygenerowany przez kompilator. Wyjscie: naglowek .h."""
import re, sys

ASCII = re.compile(r'^[ \t]*\.ascii[ \t]*"(.*)".*$')


def convert(s_path, h_path, guard):
    out = ["#ifndef " + guard, "#define " + guard, "/*", " * DO NOT MODIFY.", " *",
           " * This file was generated by Kbuild", " */", ""]
    for line in open(s_path, encoding="utf-8", errors="replace"):
        line = line.rstrip("\n").rstrip("\r")
        m = ASCII.match(line)
        if not m:
            continue
        v = m.group(1)
        if not v.startswith("->"):
            continue
        # ->#comment  ->  /* comment */
        m2 = re.match(r"^->#(.*)$", v)
        if m2:
            out.append("/* " + m2.group(1) + " */")
            continue
        # ->NAME [$#]*VALUE REST  ->  #define NAME VALUE /* REST */
        m3 = re.match(r"^->([^ ]*) [\$#]*([^ ]*) (.*)$", v)
        if m3:
            out.append("#define %s %s /* %s */" % m3.groups())
            continue
        out.append(v.replace("->", "", 1))
    out += ["", "#endif"]
    with open(h_path, "w", newline="\n") as f:
        f.write("\n".join(out) + "\n")
    n = len([x for x in out if x.startswith("#define")])
    print("%s: %d definicji" % (h_path, n))


if __name__ == "__main__":
    convert(sys.argv[1], sys.argv[2], sys.argv[3])
